def summarize(read_value):
    count = 0
    total = 0
    low = high = None
    while count < 5:
        value = read_value()
        if type(value) is int and 0 <= value <= 1000:
            if count == 0:
                low = high = value
            if value < low:
                low = value
            if value > high:
                high = value
            total += value
            count += 1
    return low, high, total / count

